-- hrm.rpt_leave_balances: Leave balances per employee, leave type and leave year (FR-HRM-LVE-10): what was added, taken, adjusted and taken off, and the balance, as the ledger sums them, with the unit, branch and location in force now. No pay or salary column (FR-HRM-GHR-06). Read-only; data scope is applied by the report service.
create or replace view hrm.rpt_leave_balances with (security_invoker = true) as
select l.company_id, l.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       l.leave_type_id, t.code as leave_type_code, t.unit, l.leave_year,
       coalesce(sum(l.quantity) filter (where l.kind in ('opening', 'accrual', 'grant', 'comp_off_earned', 'transfer_in') or (l.kind = 'carry_forward' and l.quantity > 0)), 0) as added,
       coalesce(-sum(l.quantity) filter (where l.kind in ('usage', 'usage_reversal')), 0) as used,
       coalesce(sum(l.quantity) filter (where l.kind = 'adjustment'), 0) as adjusted,
       coalesce(-sum(l.quantity) filter (where l.kind in ('lapse', 'encashment', 'comp_off_expired', 'transfer_out') or (l.kind = 'carry_forward' and l.quantity < 0)), 0) as removed,
       sum(l.quantity) as balance
from hrm.leave_ledger l
join hrm.employments e on e.id = l.employment_id
join hrm.persons p on p.id = e.person_id
join hrm.leave_types t on t.id = l.leave_type_id
left join hrm.employment_assignments a on a.employment_id = l.employment_id and a.valid_to is null
group by l.company_id, l.employment_id, e.employee_no, p.first_name, p.last_name, a.org_unit_id, a.branch_id, a.location_id, l.leave_type_id, t.code, t.unit, l.leave_year;
grant select on hrm.rpt_leave_balances to app_rw, app_ro, backup;

-- hrm.rpt_leave_taken: Leave taken per employee, leave type and month (FR-HRM-LVE-10): the quantity of approved leave days (and of leave whose cancellation waits), of which unpaid, and the number of requests, with the unit, branch and location of the day. No pay or salary column (FR-HRM-GHR-06).
create or replace view hrm.rpt_leave_taken with (security_invoker = true) as
select d.company_id, d.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       r.leave_type_id, t.code as leave_type_code, t.unit,
       date_trunc('month', d.leave_date)::date as month,
       count(distinct d.leave_request_id) as requests,
       sum(d.quantity) as taken,
       coalesce(sum(d.quantity) filter (where not d.is_paid), 0) as unpaid
from hrm.leave_request_days d
join hrm.leave_requests r on r.id = d.leave_request_id
join hrm.employments e on e.id = d.employment_id
join hrm.persons p on p.id = e.person_id
join hrm.leave_types t on t.id = r.leave_type_id
left join hrm.employment_assignments a
       on a.employment_id = d.employment_id and a.valid_from <= d.leave_date and (a.valid_to is null or a.valid_to > d.leave_date)
where d.request_status in ('approved', 'cancel_requested')
group by d.company_id, d.employment_id, e.employee_no, p.first_name, p.last_name, a.org_unit_id, a.branch_id, a.location_id, r.leave_type_id, t.code, t.unit, date_trunc('month', d.leave_date)::date;
grant select on hrm.rpt_leave_taken to app_rw, app_ro, backup;

-- hrm.rpt_leave_pending: Leave requests waiting for a decision (submitted, or a cancellation asked for), one row per request, with the unit, branch and location on its first day (FR-HRM-LVE-05, RPT-05). No pay or salary column (FR-HRM-GHR-06).
create or replace view hrm.rpt_leave_pending with (security_invoker = true) as
select r.id as request_id, r.company_id, r.request_no, r.employment_id, e.employee_no, p.first_name, p.last_name,
       a.org_unit_id, a.branch_id, a.location_id,
       r.leave_type_id, t.code as leave_type_code, t.unit,
       r.start_date, r.end_date, r.days, r.status, r.created_at as requested_at
from hrm.leave_requests r
join hrm.employments e on e.id = r.employment_id
join hrm.persons p on p.id = e.person_id
join hrm.leave_types t on t.id = r.leave_type_id
left join hrm.employment_assignments a
       on a.employment_id = r.employment_id and a.valid_from <= r.start_date and (a.valid_to is null or a.valid_to > r.start_date)
where r.status in ('submitted', 'cancel_requested');
grant select on hrm.rpt_leave_pending to app_rw, app_ro, backup;
